Given an unsorted array in which all numbers occur an even number of times except two numbers that occur an odd number of times. Return those two numbers.Examples: Input: [12, 23, 34, 12, 12, 23, 12, 45]Output: [34, 45]Input: [4, 4, 100, 5000, 4, 4, 4, 4, 100, 100]Output: [100, 5000]Input: [10, 20]Output: [10, 20]Try It YourselfTable of Content[Naive Approach] - O(n^2) time and O(1) space[Better Approach - 1] Using Sorting - O(n logn) time and O(1) space[Better Approach - 2] Using Hash Map - O(n) time and O(n) space[Expected Approach] Using Bit Manipulation - O(n) time and O(1) space[Naive Approach] - O(n^2) time and O(1) spaceThe idea is to run two nested loops. The outer loop picks an element and the inner loop counts the number of occurrences of the picked element. If the count of occurrences is odd, then append the element to result, while ensuring that one element is only pushed once into result.
            C++

    #include <iostream>
#include<vector>
#include<algorithm>
using namespace std;

// Function to find the two elements
// with odd occurrences.
vector<int> twoOddNum(vector<int>& arr) {
    int n = arr.size();

    vector<int> ans = {-1, -1};
    int index = 0;

    // Check for each element
    for (int i=0; i<n; i++) {

        // Get the count of arr[i]
        int cnt = 0;
        for (int j=0; j<n; j++) {
            if (arr[j]==arr[i]) cnt++;
        }

        // If cnt is odd and arr[i]
        // has not been added to result yet.
        if (cnt%2==1 && ans[0]!=arr[i] && ans[1]!=arr[i]) {
            ans[index++] = arr[i];
        }
    }

    // Return in decreasing order
    if (ans[0]<ans[1]) swap(ans[0], ans[1]);

    return ans;
}

int main() {
    vector<int> arr = {12, 23, 34, 12, 12, 23, 12, 45};
    vector<int> ans = twoOddNum(arr);
    cout<<ans[0]<<" "<<ans[1]<<endl;
    return 0;
}


