    // odd occurrences in an unsorted array
#include <iostream>
#include <vector> 
using namespace std;

// Function to find the two elements
// with odd occurrences.
vector<int> twoOddNum(vector<int>& arr) {
    int n = arr.size();

    // Get the XOR of the two
    // numbers we need to find
    int xorVal = 0;
    for (int i=0; i<n; i++) {
        xorVal = arr[i] ^ xorVal;
    }

    // Get its last set bit
    xorVal &= -xorVal;

    vector<int> ans(2, 0);

    for (int i=0; i<n; i++) {
        int num = arr[i];

        // If bit is not set, it 
        // belongs to first set.
        if ((num & xorVal) == 0) { 
            ans[0] ^= num;
        }

        // If bit is set, it 
        // belongs to 2nd set.
        else { 
            ans[1] ^= num;
        }
    }

    // Return in decreasing order
    if (ans[0]<ans[1]) swap(ans[0], ans[1]);

    return ans;
}

